}

solution:
std::vector<double> stable_softmax(const std::vector<double>& z) {
    const double m=*std::max_element(z.begin(),z.end());
    std::vector<double> p;double sum=0;
    for(double x:z){p.push_back(std::exp(x-m));sum+=p.back();}
    for(double& x:p) x/=sum;
    return p;
}

