solution:
std::vector<double> clip_norm(const std::vector<double>& g, double limit) {
    double sum=0;for(double v:g)sum+=v*v;
    const double norm=std::sqrt(sum);
    const double scale=norm>limit?limit/norm:1;
    auto out=g;for(double& v:out)v*=scale;
    return out;
}

